import React, { useEffect, useRef } from "react";
import Menu from "./Menu";

const TopBar = () => {
  const widgetRef = useRef(null);

  useEffect(() => {
    // 1. Cleanup purana widget
    const currentContainer = widgetRef.current;
    if (currentContainer) {
      currentContainer.innerHTML = "";
    }

    // 2. Script create karo
    const script = document.createElement("script");
    script.src = "https://s3.tradingview.com/external-embedding/embed-widget-tickers.js";
    script.async = true;
    script.type = "text/javascript";

    // Sabse important line: Script error (bundle.js) hatane ke liye
    script.crossOrigin = "anonymous"; 

    script.innerHTML = JSON.stringify({
      "symbols": [
        { "proName": "FOREXCOM:NSXUSD", "title": "NIFTY 50" },
        { "proName": "INDEX:SENSEX", "title": "SENSEX" }
      ],
      "colorTheme": "light",
      "isTransparent": true,
      "showSymbolLogo": false,
      "locale": "in"
    });

    if (currentContainer) {
      currentContainer.appendChild(script);
    }

    // 3. Cleanup on unmount
    return () => {
      if (currentContainer) {
        currentContainer.innerHTML = "";
      }
    };
  }, []);

  return (
    <div className="topbar-container" style={{ 
      display: "flex", 
      justifyContent: "space-between", 
      alignItems: "center",
      padding: "5px 20px",
      borderBottom: "1px solid #eee",
      backgroundColor: "#fff",
      height: "60px"
    }}>
      {/* Ref use kiya hai id ki jagah crash rokne ke liye */}
      <div ref={widgetRef} style={{ width: "450px", overflow: "hidden" }}></div>

      <Menu />
    </div>
  );
};

export default TopBar;
